  };
  return `...${levelInstructions[userLevel]}...`;
}

function roleToUserLevel(role: UserRole): UserLevel {
  if (role === "worker") return "basic";
  if (role === "manager") return "manager";
  return "technical"; // engineer, it_admin
}
