## JavaScript / Node.js

```javascript
const BASE_URL = "http://192.168.1.100:3000";
const API_KEY = "mk_your-machine-key";
const AUTH_HEADERS = { "Authorization": `Bearer ${API_KEY}` }; // ưu tiên hơn body apiKey

// ─── Query helper (GET) ──────────────────────────────────
async function trpcQuery(path, input) {
  input.apiKey = API_KEY; // vẫn cần trong body cho procedure có ràng buộc
  const encoded = encodeURIComponent(JSON.stringify({ json: input }));
  const url = `${BASE_URL}/api/trpc/${path}?input=${encoded}`;
  const res = await fetch(url, { headers: AUTH_HEADERS });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return data.result.data.json;
}

// ─── Mutation helper (POST) ──────────────────────────────
async function trpcMutate(path, input) {
  input.apiKey = API_KEY;
  const url = `${BASE_URL}/api/trpc/${path}`;
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...AUTH_HEADERS },
    body: JSON.stringify({ json: input }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return data.result.data.json;
}

// ─── Sử dụng ─────────────────────────────────────────────
async function main() {
  // Heartbeat
  await trpcMutate("machineApi.heartbeat", { apiKey: API_KEY });

  // Submit inspection — serialNumber + overallResult BẮT BUỘC; mỗi measurement có "result".
  const result = await trpcMutate("machineApi.submitInspection", {
    serialNumber: "SN-00001",
    overallResult: "OK",              // "OK" | "NG" | "NTF"
    productModel: "PROD-A",
    batchNumber: "LOT-2024-001",
    idempotencyKey: crypto.randomUUID(),
    inspectionTime: new Date().toISOString(),
    measurements: [
      { pointCode: "CHECK-01", measuredValue: 5.02, result: "OK" },
      { pointCode: "VISUAL-01", measuredValue: "OK", result: "OK" },
    ],
  });
  // { success, inspectionId } — hoặc { duplicate:true } / { queued:true, inspectionId:null }
  console.log(result.queued ? `Queued ${result.submissionId}` : `Inspection #${result.inspectionId}`);

  // Upload ảnh bổ sung cho 1 điểm (Node.js with fs)
  const fs = require("fs");
  const imageBase64 = fs.readFileSync("check.jpg").toString("base64");
  if (result.inspectionId) {
    await trpcMutate("machineApi.uploadImage", {
      apiKey: API_KEY,
      inspectionId: result.inspectionId,
      pointCode: "CHECK-01",
      imageBase64,
    });
  }
}

| Giá trị gốc (API) | Kết quả (Fit) |
|--------------------|---------------|
| positionX = 960 | displayX = 960 × 0.4167 + 0 = **400** |
| positionY = 540 | displayY = 540 × 0.4167 + 25 = **250** |
| radius = 50 | displayRadius = 50 × 0.4167 = **20.83** |

### Code mẫu (C# — Fit mode)

```csharp
double scale = Math.Min(
    (double)pictureBox.Width  / imageWidth,
    (double)pictureBox.Height / imageHeight);
double offsetX = (pictureBox.Width  - imageWidth  * scale) / 2;
double offsetY = (pictureBox.Height - imageHeight * scale) / 2;

int drawX = (int)(positionX * scale + offsetX);
int drawY = (int)(positionY * scale + offsetY);
int drawR = (int)(radius * scale);

g.DrawEllipse(pen, drawX - drawR, drawY - drawR, drawR * 2, drawR * 2);
```

### Code mẫu (JavaScript / Canvas — Fit mode)

```javascript
const scale = Math.min(
    canvas.width  / imageWidth,
    canvas.height / imageHeight);
const offsetX = (canvas.width  - imageWidth  * scale) / 2;
const offsetY = (canvas.height - imageHeight * scale) / 2;

const drawX = positionX * scale + offsetX;
const drawY = positionY * scale + offsetY;
const drawR = radius * scale;

ctx.beginPath();
ctx.arc(drawX, drawY, drawR, 0, Math.PI * 2);
ctx.stroke();
```

> **Lưu ý:** API còn trả về `normalizedX`, `normalizedY`, `normalizedRadius` (giá trị 0.0–1.0). Với **Stretch**: `displayX = normalizedX × canvasWidth`. Với **Fit/Fill/Center**: vẫn cần tính offset nên dùng `positionX` + `imageWidth` sẽ chính xác hơn.

